import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int l = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());

        char[][] map = new char[l][];
        int startR = -1, startC = -1;

        for (int r = 0; r < l; r++) {
            map[r] = br.readLine().trim().toCharArray();
            for (int col = 0; col < c; col++) {
                if (map[r][col] == 'o') {
                    startR = r;
                    startC = col;
                }
            }
        }

        int prevR = startR;
        int prevC = startC;
        int currR = -1, currC = -1;

        for (int d = 0; d < 4; d++) {
            int nr = startR + DR[d];
            int nc = startC + DC[d];
            if (nr >= 0 && nr < l && nc >= 0 && nc < c && map[nr][nc] == 'H') {
                currR = nr;
                currC = nc;
                break;
            }
        }

        while (true) {
            int nextR = -1, nextC = -1;

            for (int d = 0; d < 4; d++) {
                int nr = currR + DR[d];
                int nc = currC + DC[d];

                if (nr >= 0 && nr < l && nc >= 0 && nc < c
                        && map[nr][nc] == 'H'
                        && (nr != prevR || nc != prevC)) {
                    nextR = nr;
                    nextC = nc;
                    break;
                }
            }

            if (nextR == -1) {
                break;
            }

            prevR = currR;
            prevC = currC;
            currR = nextR;
            currC = nextC;
        }

        System.out.println((currR + 1) + " " + (currC + 1));
    }
}
